-- =============================================================================
--  SIRCOVA: DATOS DE PRUEBA para MySQL (vacunacion_ddriss, modelo v0.8)
--  Fecha: 2026-10-18
--
--  TODO ES FICTICIO: personas, teléfonos, correos, poblaciones y cantidades de
--  dosis se inventaron para probar el sistema. No son datos del MSPAS.
--  Como todo el sistema, solo hay datos agregados (cantidades de dosis).
--
--  Cómo usarlo:
--    1. Ejecutar antes 01_modelo_relacional_mysql.sql (crea la base vacía con
--       sus catálogos). Este script asume esa base recién creada: usa ids fijos.
--    2. Ejecutar este script completo (en Workbench, el botón del rayo).
--    3. Para volver a empezar: correr otra vez el 01 y después este script.
--  Si este script falla a medias, no lo repitas encima: vuelve a correr el 01.
--
--  Escenario: "hoy" es el 18/10/2026.
--    - Enero a agosto 2026 cerrados: los 31 formularios 5C de cada mes con
--      Hexavalente (esquema v1). Marzo de Tacaná tiene una rectificación
--      aplicada, julio de Comitancillo una solicitud pendiente y agosto de
--      San Rafael Pie de la Cuesta está en Rectificación.
--    - Septiembre abierto (fecha límite 10/10/2026): 26 reportes en todos los
--      estados del flujo, con Hexavalente v2, BCG, VPH, Td y Polio (los
--      esquemas vigentes del script 02); 5 establecimientos aún no envían.
--    - Octubre abierto, sin reportes todavía.
--    - Una corrida de indicadores con corte a agosto (cobertura, avance contra
--      la meta del mes, brecha y deserción de Hexavalente 3.ª dosis), alertas
--      y bitácora de ejemplo.
--
--  Usuarios de prueba (todos con la contraseña  Prueba#2026 , hash bcrypt):
--    admin.prueba        ADMINISTRADOR
--    estadigrafa         REVISOR (estadígrafa)
--    revisor2            REVISOR
--    epidemiologia       EPIDEMIOLOGIA
--    autoridad.sm        AUTORIDAD de la DDRISS San Marcos
--    autoridad.nacional  AUTORIDAD nacional (sin DDRISS)
--    cs1201 ... cs1230   ESTABLECIMIENTO, un usuario por centro de salud
--                        (el número es el código INE del municipio)
--    hosp.sm             ESTABLECIMIENTO del Hospital de San Marcos
--    cs1202.anterior     cuenta desactivada (para probar el inicio de sesión)
-- =============================================================================

USE vacunacion_ddriss;
START TRANSACTION;

