-- Resumen: debe mostrar las filas cargadas en las tablas principales.
SELECT 'establecimiento' AS tabla, COUNT(*) AS filas FROM establecimiento
UNION ALL SELECT 'usuario', COUNT(*) FROM usuario
UNION ALL SELECT 'poblacion_objetivo', COUNT(*) FROM poblacion_objetivo
UNION ALL SELECT 'reporte_produccion', COUNT(*) FROM reporte_produccion
UNION ALL SELECT 'detalle_produccion', COUNT(*) FROM detalle_produccion
UNION ALL SELECT 'resultado_indicador', COUNT(*) FROM resultado_indicador
UNION ALL SELECT 'alerta', COUNT(*) FROM alerta;
